export default function Sidebar({ role, onLogout, error }) {
  const navigation = navigationConfig[role] || [];
  
  const getRoleDisplayName = (role) => {
    const roleNames = {
      resident: "Resident",
      security: "Security Guard",
      admin: "Administrator"
    };
    return roleNames[role] || role;
  };

  return (
    <aside 
      className="sidebar flex flex-col h-full"
      role="navigation"
      aria-label="Main navigation"
    >
      {/* Header */}
      <div className="mb-8">
        <div className="flex items-center gap-3 mb-4">
          <div className="w-8 h-8 bg-green-600 rounded-lg flex items-center justify-center">
            <svg className="w-5 h-5 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" />
            </svg>
          </div>
          <h2 className="text-xl font-bold text-slate-200">SecureGate</h2>
        </div>
        
        {role && (
          <Badge variant="info" size="sm" className="mb-4">
            {getRoleDisplayName(role)}
          </Badge>
        )}
        
        {error && (
          <div className="mb-4 p-3 bg-red-900 border border-red-700 rounded-lg">
            <p className="text-red-200 text-sm" role="alert">
              {error}
            </p>
          </div>
        )}
      </div>

      {/* Navigation Links */}
      <nav className="flex-1" aria-label={`${getRoleDisplayName(role)} navigation`}>
        <div className="space-y-1">
          {navigation.map((item) => (
            <NavigationLink
              key={item.path}
              to={item.path}
              icon={item.icon}
              description={item.description}
              badge={item.badge}
            >
              {item.label}
            </NavigationLink>
          ))}
        </div>
      </nav>

      {/* Logout Button */}
      <div className="mt-auto pt-4 border-t border-slate-700">
        <Button 
          variant="outline" 
          className="w-full justify-center"
          onClick={onLogout}
          icon={
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M17 16l4-4m0 0l-4-4m4 4H7m6 4v1a3 3 0 01-3 3H6a3 3 0 01-3-3V7a3 3 0 013-3h4a3 3 0 013 3v1" />
            </svg>
          }
        >
          Logout
        </Button>
      </div>
    </aside>
  );
}
